import {WORLD} from './world-data.js?v=0.9.0';
import {CASES} from './history-v8.js?v=0.9.0';
import {DESTINIES,destinyRate,travelCost} from './destiny.js?v=0.9.0';
export {WORLD};
export const PATHS=['人间','修仙','修神','宇宙','多元'];
export const LIFESPANS=[[],[180,240,360,600,1000,1600,2600,4200,6800,10000],[20000,40000,80000,160000,320000,640000,1280000,2560000,5120000],[10000000,25000000,60000000,150000000],[500000000,1000000000,2000000000,5000000000]];
export function lifespanAt(s){const w=s.world;return w?.path>0?LIFESPANS[w.path]?.[w.rank]||180:s.lifespan;}
export function trialYears(s){return Math.max(1,Math.floor(lifespanAt(s)/100));}
export const trialDays=s=>trialYears(s)*365;
export function timeSteps(s){const max=trialDays(s),steps=[1,7,30,365];for(let years=10;years*365<=max;years*=10)steps.push(years*365);if(!steps.includes(max))steps.push(max);return steps;}
export function totalAge(s){return s.day/365+(s.world?.days||0)/365;}
function evolve(w,s){if(w.lifespan===undefined)w.lifespan=Math.max(lifespanAt(s),Math.ceil(totalAge(s))+trialYears(s)*30);if(w.nextTrialDay===undefined)w.nextTrialDay=w.pending?w.days:(Math.floor(w.days/trialDays(s))+1)*trialDays(s);if(w.expired===undefined)w.expired=false;if(w.deathReason===undefined)w.deathReason='';if(w.fatePoints===undefined)w.fatePoints=0;if(w.fateChanges===undefined)w.fateChanges=0;if(w.usedCaseIds===undefined)w.usedCaseIds=[];return w;}
export function initWorld(s,country=0){if(!s.world)s.world={schema:1,country,planet:0,universe:0,path:0,rank:0,cycle:0,days:0,power:0,virtue:0,practice:0,strain:0,domain:null,visitedCountries:[country],visitedPlanets:[0],visitedUniverses:[0],pending:null,chronicle:[],completed:0,failures:0};return evolve(s.world,s);}
export function validateWorld(s){if(!s.world)return;const w=initWorld(s),integer=x=>Number.isSafeInteger(x)&&x>=0;const fail=()=>{throw Error('诸天存档无效');};if(w.schema!==1||!integer(w.country)||!WORLD.countries[w.country]||!integer(w.planet)||!WORLD.planets[w.planet]||!integer(w.universe)||!WORLD.universes[w.universe]||!integer(w.path)||w.path>4||!integer(w.rank)||w.rank>=ranks(w.path).length)fail();for(const k of ['cycle','days','practice','completed','failures'])if(!integer(w[k])||w[k]>100000000000000)fail();for(const k of ['power','virtue','strain'])if(!Number.isFinite(w[k])||w[k]<0||w[k]>1e15)fail();if(!Number.isSafeInteger(w.lifespan)||w.lifespan<70||w.lifespan>1e12||!Number.isSafeInteger(w.nextTrialDay)||w.nextTrialDay<w.days||typeof w.expired!=='boolean'||typeof w.deathReason!=='string'||!integer(w.fatePoints)||!integer(w.fateChanges)||!Array.isArray(w.usedCaseIds)||w.usedCaseIds.length>32||new Set(w.usedCaseIds).size!==w.usedCaseIds.length||w.usedCaseIds.some(id=>!CASES.some(c=>c.id===id)))fail();if(w.pending?.caseId&&!CASES.some(c=>c.id===w.pending.caseId))fail();if(w.strain>100||!(w.domain===null||(integer(w.domain)&&WORLD.domains[w.domain])))fail();for(const [key,max] of [['visitedCountries',100],['visitedPlanets',12],['visitedUniverses',9]])if(!Array.isArray(w[key])||w[key].length>max||new Set(w[key]).size!==w[key].length||w[key].some(i=>!integer(i)||i>=max))fail();if(!w.visitedCountries.includes(w.country)||!w.visitedPlanets.includes(w.planet)||!w.visitedUniverses.includes(w.universe)||!Array.isArray(w.chronicle)||w.chronicle.length>200||w.chronicle.some(x=>typeof x!=='string'||x.length>2000))fail();if(w.pending&&(!integer(w.pending.serial)||w.pending.serial!==w.cycle||!integer(w.pending.kind)||w.pending.kind>11))fail();if(w.path>=2&&w.domain===null)fail();if(w.path>0&&s.ended)fail();}
export function ranks(path){return [ ['凡尘历练'],WORLD.immortals,WORLD.gods,WORLD.cosmic,WORLD.multiverse][path]||[];}
export const title=s=>{const w=initWorld(s);return ranks(w.path)[w.rank];};
function note(s,text){const w=initWorld(s);w.chronicle.unshift(`${PATHS[w.path]} · ${w.days}日｜${text}`);w.chronicle=w.chronicle.slice(0,200);}
export function entryReasons(s){return [s.ended?'此生已经结束，无法复活':'',s.pending||s.transition||s.familyChoice?'请先完成当前人生选择':'',Math.floor(s.day/365)<60&&s.progress<1?'年满60岁或抵达国家主席':'',s.stats.some(x=>x<=100)?'五维均超过100':'',s.xian<1?'至少保有1点仙值':''].filter(Boolean);}
export function enterImmortal(s){const w=initWorld(s);if(w.path!==0||entryReasons(s).length)return false;s.xian--;w.path=1;w.rank=0;w.lifespan=180;w.nextTrialDay=365;w.expired=false;w.power=0;w.practice=0;w.virtue=0;w.days=0;w.pending=null;note(s,'辞别凡尘，启灵入道。凡间年龄、任职与家族停留于此日，另记道历；原寿命兑换仍适用于凡间。');return true;}
export function canTravel(s,kind,id){const w=initWorld(s);if(!Number.isInteger(id)||s.ended||w.expired||w.pending||s.pending||s.transition||s.familyChoice)return false;if(kind==='country')return !!WORLD.countries[id]&&w.path===0&&Math.floor(s.day/365)>=18&&s.stage==='work'&&w.country!==id&&w.cycle<Math.floor(s.day/365);if(kind==='planet')return !!WORLD.planets[id]&&w.path>=2&&w.power>=travelCost(s)&&w.planet!==id;if(kind==='universe')return !!WORLD.universes[id]&&w.path===4&&w.power>=travelCost(s)&&w.universe!==id;return false;}
export function travel(s,kind,id){if(!Number.isInteger(id)||!canTravel(s,kind,id))return false;const w=initWorld(s);const [field,list,items]=kind==='country'?['country','visitedCountries',WORLD.countries]:kind==='planet'?['planet','visitedPlanets',WORLD.planets]:['universe','visitedUniverses',WORLD.universes];w[field]=id;if(!w[list].includes(id))w[list].push(id);note(s,`抵达${items[id].name}${kind==='country'?'，开始外交驻访，凡间任职档案保留原籍':''}。`);if(kind!=='country'){w.power-=travelCost(s);w.strain=Math.min(100,w.strain+5);}return true;}
export function chooseDomain(s,id){const w=initWorld(s);if(w.expired||w.path!==1||w.rank!==9||w.pending||!WORLD.domains[id]||!Number.isInteger(id))return false;w.domain=id;return true;}
export function requirements(s){const w=initWorld(s),r=w.rank+1;return {power:Math.round((w.path===1?100:w.path===2?320:w.path===3?800:1800)*r*r),virtue:r*(w.path===1?2:w.path===2?3:5),practice:r*2,balance:.25,strain:60};}
export function breakthroughReasons(s){const w=initWorld(s),g=requirements(s),reasons=[];if(w.path===0)return ['先开启修仙'];if(w.expired)return ['寿元耗尽，无法突破'];if(w.pending)reasons.push('先完成历练抉择');if(w.power<g.power)reasons.push(`修为 ${Math.floor(w.power)} / ${g.power}`);if(w.virtue<g.virtue)reasons.push(`功德 ${w.virtue} / ${g.virtue}`);if(w.practice<g.practice)reasons.push(`实践 ${w.practice} / ${g.practice}`);if(Math.min(...s.stats)/Math.max(...s.stats)<g.balance)reasons.push('五维最低值须达到最高值的25%');if(w.strain>g.strain)reasons.push('心劫须降至60以内');if(w.path===1&&w.rank===9&&w.domain===null)reasons.push('选择一个神职');if(w.path===2&&w.rank===8&&w.visitedPlanets.length<3)reasons.push('至少踏访3颗星球');if(w.path===3&&w.rank===3&&w.visitedPlanets.length<6)reasons.push('至少踏访6颗星球');if(w.path===4&&w.rank===3&&w.visitedUniverses.length<5)reasons.push('至少联结5个宇宙');return reasons;}
export function breakthrough(s){const w=initWorld(s);if(s.ended||w.path===0||breakthroughReasons(s).length)return false;const before=title(s);if(w.path===4&&w.rank===3){if(w.completed)return false;w.completed=1;note(s,'诸界共议达成：多元秩序建立。仍可继续巡游与治理。');return true;}if(w.rank===ranks(w.path).length-1){w.path++;w.rank=0;}else w.rank++;w.power=0;w.practice=0;w.virtue=0;w.fatePoints+=2;w.lifespan=Math.max(w.lifespan,lifespanAt(s));w.nextTrialDay=w.days+trialDays(s);w.strain=Math.max(0,w.strain-15);note(s,`${before} → ${title(s)}。寿元增长至${w.lifespan.toLocaleString()}岁，问道周期${trialYears(s).toLocaleString()}年。${w.path===4&&w.rank===0?'宇宙之主之后，界外星门正式开启。':''}`);return true;}

function nextCase(s){const w=initWorld(s);let remaining=CASES.filter(c=>!w.usedCaseIds.includes(c.id));if(!remaining.length){w.usedCaseIds=[];remaining=CASES;}return remaining[(Math.imul(w.cycle+1,2654435761)>>>0)%remaining.length].id;}
function setTrial(s){const w=initWorld(s);w.cycle++;w.pending={serial:w.cycle,kind:w.cycle%12,caseId:nextCase(s)};}
export function worldEvent(s){const w=initWorld(s);if(!w.pending)return null;const c=CASES.find(c=>c.id===w.pending.caseId)||CASES[(w.pending.serial+s.seed)%CASES.length],offset=(Math.imul(w.pending.serial+1,2654435761)>>>0)%3;const country=WORLD.countries[w.country],planet=WORLD.planets[w.planet],universe=WORLD.universes[w.universe],domain=WORLD.domains[w.domain];return {id:c.id,title:c.name,source:'史鉴演练 · '+c.date,historySource:{name:c.name+' · '+c.date,fact:c.fact,url:c.url},text:`${w.path===0?country.name+' · '+country.polity:universe.name+' / '+planet.name+' · '+title(s)}。${domain?'你的神职：'+domain.name+'神，职责为'+domain.duty+'。':''}史鉴投影：${c.fact}\n情境改编：${c.dilemma}\n${w.path>0?'将此类风险映射到当前治理范围；星球法则：'+planet.law+'。':'你在外交驻访中据此提交建议，不改写现实历史。'}`,options:[0,1,2].map(i=>c.options[(i+offset)%3]),answer:(3-offset)%3,explanation:c.explanation+' 游戏判分仅针对题设目标，不代表历史只有唯一道路。'};}
export function train(s,days=30,activity=0){const w=initWorld(s);if(s.ended||w.expired||w.path===0||w.pending||!timeSteps(s).includes(days)||!Number.isInteger(activity)||activity<0||activity>4)return 0;const remaining=Math.max(0,Math.round(w.lifespan*365-s.day-w.days));const actual=Math.min(days,w.nextTrialDay-w.days,remaining);if(actual<=0)return 0;const quality=days===1?1:days===7?.85:days===30?.68:.5;w.days+=actual;const affinity=w.path>=2?WORLD.domains[w.domain].affinity:WORLD.planets[w.planet].focus,balance=Math.min(...s.stats)/Math.max(...s.stats);w.power+=actual*(.6+balance)*quality*(activity===affinity?1.2:1);for(let i=0;i<5;i++)s.stats[i]+=actual*(i===activity?.09:.025)*destinyRate(s,i);w.strain=Math.max(0,w.strain-actual*(activity===2?.3:.04));if(actual===remaining){w.expired=true;w.deathReason='道寿耗尽';note(s,'寿元耗尽，诸天旅程落幕。档案仍可导出。');}else if(w.days===w.nextTrialDay)setTrial(s);return actual;}
export function mission(s){const w=initWorld(s);if(w.path!==0||s.ended||s.pending||s.transition||s.familyChoice||w.pending||s.stage!=='work'||Math.floor(s.day/365)<18||w.cycle>=Math.floor(s.day/365))return false;w.cycle=Math.floor(s.day/365);w.pending={serial:w.cycle,kind:w.cycle%12,caseId:nextCase(s)};return true;}
export function resolveWorld(s,index){const w=initWorld(s),e=worldEvent(s);if(!e||![0,1,2].includes(index)||s.ended||w.expired)return null;const ok=index===e.answer;w.pending=null;if(!w.usedCaseIds.includes(e.id))w.usedCaseIds.push(e.id);w.practice++;if(ok){w.virtue+=3;w.power+=80;if(w.path>0)w.fatePoints++;w.strain=Math.max(0,w.strain-8);}else{w.failures++;w.power=Math.max(0,w.power-30);w.strain=Math.min(100,w.strain+18);}if(w.path>0)w.nextTrialDay=w.days+trialDays(s);note(s,`${e.title}：${e.options[index]}。${ok?'功德与实践增长':'留下心劫，可继续修复'}。${e.explanation}`);return {...e,ok,choice:e.options[index]};}
export function fateCost(s){return 8+initWorld(s).fateChanges*4;}
export function canRewrite(s){const w=initWorld(s);return !s.ended&&!w.expired&&!w.pending&&(w.path>=2||w.path===1&&w.rank===9)&&w.fatePoints>=fateCost(s);}
export function rewriteDestiny(s,id){const w=initWorld(s);if(!canRewrite(s)||!DESTINIES.some(d=>d.id===id)||id===(s.destiny||'ordinary'))return false;const old=DESTINIES.find(d=>d.id===s.destiny)?.name||'平常人家';w.fatePoints-=fateCost(s);w.fateChanges++;s.destiny=id;w.strain=Math.max(0,w.strain-10);note(s,`逆天改命：${old} → ${DESTINIES.find(d=>d.id===id).name}。只影响今后成长，不重掷既有属性，也不复活。`);return true;}
